using CommerceErp.Core;
using static CommerceErp.Infrastructure.CommerceDatabase;
namespace CommerceErp.Infrastructure;
public sealed partial class MasterDataService
{
    private static OpeningPolicy Policy(DbSession db)=>db.Query("SELECT RequireDifferentApprover,Version FROM OpeningConfiguration WHERE Id=1",r=>new OpeningPolicy(r.GetInt64(0)==1,r.GetInt64(1))).SingleOrDefault()??throw new BusinessRuleException("审核配置缺失，已阻止操作，请恢复配置。");
    public OpeningPolicy GetOpeningPolicy()=>database.Read(Policy);
    public List<OpeningPolicyChange> PolicyChanges()=>database.Read(db=>db.Query("SELECT Id,ExpectedVersion,RequireDifferentApprover,RequestedBy,State,Version,CreatedAt FROM OpeningPolicyChanges ORDER BY CreatedAt DESC,Id DESC"+db.Limit(100),r=>new OpeningPolicyChange(r.GetString(0),r.GetInt64(1),r.GetInt64(2)==1,r.GetString(3),r.GetString(4),r.GetInt64(5),r.GetString(6))));
    public MasterResult SaveOpeningPolicy(SaveOpeningPolicyRequest r)=>Command(r.OperationId,"OpeningPolicyProposal",r,r.Reason,db=>{if(SecurityContext.Current is not{} user)throw new BusinessRuleException("审核策略变更必须使用个人账号。");var old=Policy(db);if(old.Version!=r.ExpectedVersion)throw new ConflictException("审核策略已变化，请刷新。");var id=Guid.NewGuid().ToString("N");db.Execute("INSERT INTO OpeningPolicyChanges VALUES($id,$v,$r,$actor,'Pending',1,$now)",("id",id),("v",old.Version),("r",r.RequireDifferentApprover?1:0),("actor",user.User.Id),("now",Now()));History(db,"opening-policy","ProposePolicy",r.Reason,new{id,Before=old,Request=r});return new(id,1,false,"变更申请已保存，另一位策略管理员批准后才生效。");});
    public MasterResult ApprovePolicyChange(string id,ApproveOpeningRequest r)=>Command(r.OperationId,"OpeningPolicyApprove",new{id,r},r.Reason,db=>{if(SecurityContext.Current is not{} access)throw new BusinessRuleException("策略审核必须使用个人账号。");var row=db.Query("SELECT ExpectedVersion,RequireDifferentApprover,RequestedBy,State,Version FROM OpeningPolicyChanges WHERE Id=$id",x=>(Expected:x.GetInt64(0),Required:x.GetInt64(1)==1,Actor:x.GetString(2),State:x.GetString(3),Version:x.GetInt64(4)),("id",id)).SingleOrDefault();if(row.State!="Pending"||row.Version!=r.ExpectedVersion)throw new ConflictException("申请状态或版本已变化。");if(row.Actor==access.User.Id)throw new AccessDeniedException("申请人不能批准自己的策略变更。");var old=Policy(db);if(old.Version!=row.Expected)throw new ConflictException("生效策略已变化，请重新申请。");db.Execute("UPDATE OpeningConfiguration SET RequireDifferentApprover=$r,Version=Version+1 WHERE Id=1",("r",row.Required?1:0));db.Execute("UPDATE OpeningPolicyChanges SET State='Approved',Version=Version+1 WHERE Id=$id",("id",id));History(db,"opening-policy","ApprovePolicy",r.Reason,new{id,Before=old,After=new OpeningPolicy(row.Required,old.Version+1)});return new(id,row.Version+1,false,"策略已由另一账号批准；已有严格审核单据不会降低要求。");});
    public MasterResult EditOpening(string id,EditOpeningRequest r)=>Command(r.OperationId,"OpeningEdit",new{id,r},r.Reason,db=>{var old=Draft(db,id,r.ExpectedVersion);CheckOpening(db,r.Lines);db.Execute("UPDATE OpeningDocuments SET LinesJson=$lines,Reason=$reason,Version=Version+1 WHERE Id=$id",("lines",Json(r.Lines)),("reason",r.Reason),("id",id));History(db,id,"EditOpening",r.Reason,new{Before=old,After=r});return new(id,r.ExpectedVersion+1,false,"草稿已修改，未改变库存。");});
    public MasterResult VoidOpening(string id,ApproveOpeningRequest r)=>Command(r.OperationId,"OpeningVoid",new{id,r},r.Reason,db=>{var old=Draft(db,id,r.ExpectedVersion);db.Execute("UPDATE OpeningDocuments SET State='Voided',Version=Version+1 WHERE Id=$id",("id",id));History(db,id,"VoidOpening",r.Reason,old);return new(id,r.ExpectedVersion+1,false,"草稿已作废，未改变库存。");});
    private static string Draft(DbSession db,string id,long version){var row=db.Query("SELECT State,Version,LinesJson FROM OpeningDocuments WHERE Id=$id",r=>(State:r.GetString(0),Version:r.GetInt64(1),Lines:r.GetString(2)),("id",id)).SingleOrDefault();if(row.Lines is null||row.State!="Draft"||row.Version!=version)throw new ConflictException("仅可操作版本一致的待审草稿。");return row.Lines;}
    public SkuProfile SkuDetails(string id)=>database.Read(db=>Skus(db,id:id).SingleOrDefault()??throw new BusinessRuleException("商品已不存在，请刷新列表。"));
    public OpeningDocument OpeningDetails(string id)=>database.Read(db=>db.Query("SELECT Id,Number,State,Version,CreatedBy,ApprovedBy,Reason,CreatedAt,LinesJson FROM OpeningDocuments WHERE Id=$id",r=>new OpeningDocument(r.GetString(0),r.GetString(1),r.GetString(2),r.GetInt64(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),FromJson<List<OpeningLine>>(r.GetString(8))),("id",id)).SingleOrDefault()??throw new BusinessRuleException("期初单不存在，请刷新。"));
    private static void Paging(int page,int size,string search){if(page<1||page>100000||size<1||size>200||search.Length>100)throw new BusinessRuleException("页码须1–100000，每页1–200条，搜索不超过100字。");}
    public MasterPage<SkuProfile> SkuPage(int page=1,int size=50,string search="")=>database.Read(db=>{Paging(page,size,search);var where=" FROM Skus s JOIN MasterSkuData x ON x.SkuId=s.Id WHERE s.TenantId=$t AND (s.Code LIKE $q OR s.Name LIKE $q)";var args=new (string,object?)[]{("t",Tenant(db)),("q","%"+search+"%"),("offset",(page-1)*size),("limit",size)};var total=db.Scalar<int>("SELECT COUNT(*)"+where,args);var rows=db.Query("SELECT s.Id,s.Code,s.Name,s.Enabled,s.ComponentsJson,x.Unit,x.Version"+where+" ORDER BY s.Code,s.Id"+db.Page,r=>new SkuProfile(r.GetString(0),r.GetString(1),r.GetString(2),r.GetInt64(3)==1,FromJson<List<SkuComponent>>(r.GetString(4)),r.GetString(5),r.GetInt64(6)),args);return new MasterPage<SkuProfile>(rows,total,page,size);});
    public MasterPage<OpeningDocument> OpeningPage(int page=1,int size=50,string search="")=>database.Read(db=>{Paging(page,size,search);var args=new (string,object?)[]{("q","%"+search+"%"),("offset",(page-1)*size),("limit",size)};var total=db.Scalar<int>("SELECT COUNT(*) FROM OpeningDocuments WHERE Number LIKE $q",args);var rows=db.Query("SELECT Id,Number,State,Version,CreatedBy,ApprovedBy,Reason,CreatedAt,LinesJson FROM OpeningDocuments WHERE Number LIKE $q ORDER BY CreatedAt DESC,Id DESC"+db.Page,r=>new OpeningDocument(r.GetString(0),r.GetString(1),r.GetString(2),r.GetInt64(3),r.GetString(4),r.GetString(5),r.GetString(6),r.GetString(7),FromJson<List<OpeningLine>>(r.GetString(8))),args);return new MasterPage<OpeningDocument>(rows,total,page,size);});
    public MasterPage<SkuMapping> MappingPage(int page=1,int size=50,string search="")=>database.Read(db=>{Paging(page,size,search);var where=" FROM SkuMappings m LEFT JOIN MasterMappingState x ON x.TenantId=m.TenantId AND x.Platform=m.Platform AND x.ShopId=m.ShopId AND x.ProductId=m.ProductId AND x.VariantId=m.VariantId WHERE m.TenantId=$t AND (m.ProductId LIKE $q OR m.VariantId LIKE $q)";var args=new (string,object?)[]{("t",Tenant(db)),("q","%"+search+"%"),("offset",(page-1)*size),("limit",size)};var total=db.Scalar<int>("SELECT COUNT(*)"+where,args);var rows=db.Query("SELECT m.Platform,m.ShopId,m.ProductId,m.VariantId,m.SkuId,m.MultiplierUnits,m.Version,COALESCE(x.Enabled,1)"+where+" ORDER BY m.Platform,m.ShopId,m.ProductId,m.VariantId"+db.Page,r=>new SkuMapping(Tenant(db),Enum.Parse<Platform>(r.GetString(0)),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),BusinessUnits.FromQuantity(r.GetInt64(5)),r.GetInt32(6),r.GetInt64(7)==1),args);return new MasterPage<SkuMapping>(rows,total,page,size);});
    public MasterPage<UnmappedSku> UnmappedPage(int page=1,int size=50,string search="")=>database.Read(db=>{Paging(page,size,search);var count=db.Scalar<int>("SELECT COUNT(*) FROM (SELECT o.Platform,o.ShopId,x.ExternalId,l.ProductId,l.VariantId"+MissingFrom+MissingGroup+") missing",("t",Tenant(db)),("search",search));return new MasterPage<UnmappedSku>(MissingRows(db,search,page,size),count,page,size);});
}
